let PORT;
function request(method, p, body, headers = {}) {
  return new Promise((resolve, reject) => {
    const data = body === undefined ? null : Buffer.from(typeof body === 'string' ? body : JSON.stringify(body));
    const h = Object.assign({}, data ? { 'Content-Type': 'application/json', 'Content-Length': data.length } : {}, headers);
    const r = http.request({ host: '127.0.0.1', port: PORT, method, path: p, headers: h, agent: false }, (res) => {
      const chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => {
        let buf = Buffer.concat(chunks);
        const gz = /gzip/.test(res.headers['content-encoding'] || '');
        if (gz) buf = zlib.gunzipSync(buf);
        const text = buf.toString('utf8');
        let json; try { json = JSON.parse(text); } catch (_) { json = undefined; }
        resolve({ status: res.statusCode, headers: res.headers, text, json, gz, raw: buf });
      });
    });
    r.on('error', reject);
    if (data) r.write(data);
    r.end();
  });
}
