// minimal websocket client: resolves with {status} for a refused upgrade, or an open connection that collects frames
function wsOpen(p) {
  return new Promise((resolve) => {
    const key = crypto.randomBytes(16).toString('base64');
    const req = http.request({ host: '127.0.0.1', port: PORT, path: p, agent: false, headers: {
      Connection: 'Upgrade', Upgrade: 'websocket', 'Sec-WebSocket-Version': '13', 'Sec-WebSocket-Key': key } });
    req.on('response', (res) => { res.resume(); resolve({ status: res.statusCode }); });
    req.on('upgrade', (res, socket, head) => {
      // RFC 6455 4.2.2: browsers drop the connection unless Accept = base64(sha1(key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"))
      const acceptOk = res.headers['sec-websocket-accept'] === crypto.createHash('sha1').update(key + '258EAFA5-E914-47DA-95CA-C5AB0DC85B11').digest('base64');
      const c = { status: res.statusCode, acceptOk, frames: [], closeCode: null, closed: false, socket };
      let buf = Buffer.alloc(0);
      const parse = (d) => {
        buf = Buffer.concat([buf, d]);
        for (;;) {
          if (buf.length < 2) return;
          const op = buf[0] & 15;
          let len = buf[1] & 127, pos = 2;
          if (len === 126) { if (buf.length < 4) return; len = buf.readUInt16BE(2); pos = 4; }
          else if (len === 127) { if (buf.length < 10) return; len = Number(buf.readBigUInt64BE(2)); pos = 10; }
          if (buf.length < pos + len) return;
          const payload = buf.subarray(pos, pos + len);
          buf = buf.subarray(pos + len);
          if (op === 2) c.frames.push({ t: Date.now(), b: Buffer.from(payload) });
          else if (op === 8) c.closeCode = payload.length >= 2 ? payload.readUInt16BE(0) : 0;
        }
      };
      if (head && head.length) parse(head);   // bytes that arrived together with the 101 response
      socket.on('data', parse);
      socket.on('close', () => { c.closed = true; });
      socket.on('error', () => {});
      c.close = () => socket.destroy();
      resolve(c);
    });
    req.on('error', () => resolve({ status: 0 }));
    req.end();
  });
}
// SPEC.md frame check: 'H', version 1, bri, n0, n1, 3*(n0+n1) bytes
function frameOk(b) { return b.length >= 5 && b[0] === 0x48 && b[1] === 1 && b[3] <= 48 && b[4] <= 48 && b.length === 5 + 3 * (b[3] + b[4]); }

// independent parse of HG_BUILTIN_MOODS (not the parser in home_api.js)
function cppMoods() {
  const src = fs.readFileSync(CPP, 'utf8');
  const block = src.match(/HG_BUILTIN_MOODS\[\]\s*=\s*\{([\s\S]*?)\n\};/)[1];
  return block.split('\n').filter(l => /^\s*\{"/.test(l)).map(l => {
    const m = l.match(/\{"([^"]*)",\s*"([^"]*)",\s*"([^"]*)",\s*(\d+),\s*(\d+),\s*(\d+),\s*\{([^}]*)\},\s*\{([^}]*)\},\s*(true|false)\}/);
    const hex = s => s.split(',').map(x => Number(x.trim()));
    return { n: m[1], fx: m[2], pal: m[3], sx: +m[4], ix: +m[5], bri: +m[6], col: hex(m[7]), g: hex(m[8]), snd: m[9] === 'true' };
  });
}

